export const getProductosDestacados = () => productos.filter((p) => p.destacado);
export const getProductosByCategoria = (id: string) => productos.filter((p) => p.categoria === id);
export const getProductoBySlug = (slug: string) => productos.find((p) => p.slug === slug);
export const getProductosRelacionados = (categoriaId: string, slugActual: string) =>
  productos.filter((p) => p.categoria === categoriaId && p.slug !== slugActual).slice(0, 4);
export const buscarProductos = (q: string) =>
  productos.filter((p) =>
    p.nombre.toLowerCase().includes(q.toLowerCase()) ||
    p.descripcion.toLowerCase().includes(q.toLowerCase()) ||
    p.categoria.toLowerCase().includes(q.toLowerCase())
  );
